<?php $accountPayments = array_values(array_filter($payments,static fn($payment)=>(int)$payment['account_id'] === $id)); $remaining = contasRemaining($entry); $paymentToken = is_string($_POST['payment_token']??null) ? $_POST['payment_token'] : bin2hex(random_bytes(16)); ?>
<section class="a-section"><h2><?= contasEscape($entry['title']) ?></h2><div class="a-metrics"><div><span><?= contasKinds()[$entry['kind']] ?></span><strong><?= contasMoney(contasCents($entry['amount'])) ?></strong></div><div><span><?= $entry['kind'] === 'receivable' ? 'Recebido' : 'Pago' ?></span><strong><?= contasMoney(contasCents($entry['paid_amount'])) ?></strong></div><div><span>Restante</span><strong><?= contasMoney($remaining) ?></strong></div><div><span>Vencimento</span><strong><?= date('d/m/Y',strtotime($entry['due_date'])) ?></strong></div></div></section>
<?php if((int)$entry['canceled'] !== 1 && $remaining > 0): ?>
<form method="post" action="<?= contasEscape($url.'?view=movement&id='.$id) ?>" class="a-section"><?= csrf_field() ?><input type="hidden" name="operation" value="pay"><h2><?= $entry['kind'] === 'receivable' ? 'Registrar recebimento' : 'Registrar pagamento' ?></h2><div class="a-form-grid">
<label>Valor<input class="c-input" name="payment_amount" inputmode="decimal" maxlength="30" value="<?= contasEscape($_POST['payment_amount'] ?? contasDecimal($remaining)) ?>" required></label><label>Data<input class="c-input" type="date" name="paid_date" max="<?= $today ?>" value="<?= contasEscape($_POST['paid_date'] ?? $today) ?>" required></label><label>Forma<select class="c-input" name="method"><?php foreach(contasMethods() as $key=>$label): ?><option value="<?= $key ?>" <?= ($_POST['method'] ?? 'pix') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label>
</div><label class="a-notes">Observacoes<input class="c-input" name="payment_notes" maxlength="500" value="<?= contasEscape($_POST['payment_notes'] ?? '') ?>"></label><input type="hidden" name="payment_token" value="<?= contasEscape($paymentToken) ?>"><input type="hidden" name="form_complete" value="1"><div class="a-actions" style="margin-top:16px"><button class="c-btn-secondary"><?= $entry['kind'] === 'receivable' ? 'Registrar recebimento' : 'Registrar pagamento' ?></button></div></form>
<?php else: ?><p><?= (int)$entry['canceled'] === 1 ? 'Conta cancelada.' : 'Conta quitada.' ?></p><?php endif; ?>
<section class="a-section"><h2>Historico de movimentacoes</h2><div class="a-scroll"><table class="c-table"><thead><tr><th>Data</th><th>Valor</th><th>Forma</th><th>Observacoes</th><th>Acoes</th></tr></thead><tbody><?php foreach($accountPayments as $payment): ?><tr><td><?= date('d/m/Y',strtotime($payment['paid_date'])) ?></td><td><?= contasMoney(contasCents($payment['amount'])) ?></td><td><?= contasMethods()[$payment['method']] ?? contasEscape($payment['method']) ?></td><td><?= contasEscape($payment['notes']) ?></td><td><form method="post" data-contas-confirm="Excluir esta movimentacao e devolver seu valor ao restante em aberto?"><?= csrf_field() ?><input type="hidden" name="operation" value="remove_payment"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="payment_id" value="<?= (int)$payment['id'] ?>"><button class="c-btn-secondary">Excluir movimentacao</button></form></td></tr><?php endforeach; ?><?php if(!$accountPayments): ?><tr><td colspan="5">Nenhuma movimentacao registrada.</td></tr><?php endif; ?></tbody></table></div></section>
